# Public-release copy: file paths were converted to repository-relative paths.
# Statistical logic, parameters, thresholds, and seeds are unchanged from the archived final script.
script_dir <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(), value=TRUE)[1]))); source(file.path(dirname(script_dir), "02_singlecell_preprocessing", "common.R"))
base<-file.path(paths$external_data_root, "singlecell", "scTenifold_runs", "Figure5_GART_virtual_KO_5seed_FINAL");seeds<-c(1234,2024,7777,8888,9999);all<-list()
for(s in seeds){f<-file.path(base,paste0("Fig5_scTenifoldKnk_GART_KO_seed_",s,"_full_results.csv"));d<-read.csv(f,check.names=FALSE);if(!"gene"%in%names(d))names(d)[1]<-"gene";rankcol<-grep("^rank$",names(d),ignore.case=TRUE,value=TRUE)[1];distcol<-grep("distance|dManifold",names(d),ignore.case=TRUE,value=TRUE)[1];if(is.na(rankcol))d$rank<-rank(-d[[distcol]],ties.method="min") else d$rank<-d[[rankcol]];d$distance<-d[[distcol]];d$seed<-s;all[[as.character(s)]]<-d[,c("gene","seed","rank","distance")]}
long<-do.call(rbind,all);cons<-aggregate(cbind(rank,distance)~gene,long,function(v)median(v,na.rm=TRUE));names(cons)[2:3]<-c("median_rank","median_distance");best<-aggregate(rank~gene,long,min);names(best)[2]<-"best_rank";n100<-aggregate(rank~gene,long,function(v)sum(v<=100,na.rm=TRUE));names(n100)[2]<-"n_top100";nseed<-aggregate(seed~gene,long,function(v)length(unique(v[is.finite(v)])));names(nseed)[2]<-"n_seeds_tested";rank_iqr<-aggregate(rank~gene,long,IQR,na.rm=TRUE);names(rank_iqr)[2]<-"rank_IQR";cons<-Reduce(function(x,y)merge(x,y,by="gene"),list(cons,best,n100,nseed,rank_iqr));cons$top100_recurrence<-cons$n_top100/cons$n_seeds_tested;cons<-cons[order(cons$median_rank),];write.csv(long,file.path(output_root,"RESULTS","scTenifold_5iteration_long.csv"),row.names=FALSE);write.csv(cons,file.path(output_root,"RESULTS","scTenifold_consensus_ranking.csv"),row.names=FALSE)
sets<-read_corrected()$public_gene_sets;mods<-do.call(rbind,lapply(names(sets),function(nm){g<-intersect(sets[[nm]],cons$gene);x<-cons$median_rank[match(g,cons$gene)];bg<-cons$median_rank[!cons$gene%in%g];wt<-wilcox.test(x,bg,alternative="less",exact=FALSE);data.frame(module=nm,n_genes=length(g),median_rank=median(x),median_percentile=median(x)/nrow(cons),enrichment_P=wt$p.value)}));mods$FDR<-p.adjust(mods$enrichment_P,"BH");write.csv(mods,file.path(output_root,"RESULTS","scTenifold_module_perturbation.csv"),row.names=FALSE)
write.csv(data.frame(method="scTenifoldKnk",iterations=5,seeds=paste(seeds,collapse="|"),evidence_grade="exploratory",reason="Virtual perturbation is not donor-aware functional validation; reproducibility is summarized across seeds."),file.path(output_root,"AUDIT","scTenifold_method_audit.csv"),row.names=FALSE)
